//! The matrices rule family — `declared-test-matrices` (R-060): a test
//! matrix is DECLARED as data (a table of cases iterated once), never
//! GENERATED by a full `2^n` enumeration. The two compliant idioms are a
//! case table + one loop (Rust `for case in CASES`, Go `for _, tc :=
//! range tests`, TS `it.each([...])`), and the two violations are a
//! bit-mask loop (`for mask in 0..(1 << n)`) and a Cartesian product of
//! three or more nested loops. The extractor emits one `Fact::TestSweep`
//! per violation in test context; this rule turns each into a finding.

specmark::scope!("spec://org.vibevm.ai-native/core-ai-native/mechanisms/ENGINE-CONFORM-v0.1#rules");

use crate::facts::{Fact, SourceFacts};
use crate::finding::{Finding, Rule};

use super::req_message;

/// The declared-test-matrices card (R-060). Authored in the Rust
/// projection — its lineage home — and cited by name; the rule serves all
/// three stacks (Rust, Go, TypeScript) since every frontend emits the same
/// `Fact::TestSweep` in test context. The card name is identical should a
/// per-projection or neutral home be chosen later (a one-line edit of this
/// constant, mirroring the naming rule's provisional-home posture).
const MATRICES_CARD: &str =
    "discipline://rust-ai-native-lang/cards/rule-declared-test-matrices#ops";

/// R-060 — `declared-test-matrices`: a test matrix is declared as data and
/// iterated once, never swept by a full enumeration. A `Fact::TestSweep`
/// (`kind` = `"bitmask"` or `"nested-loops"`) is exactly the smell the rule
/// exists to red — a bit-mask loop `for mask in 0..(1 << n)` or a Cartesian
/// product of three-or-more nested loops, both of which hide a case count
/// that grows exponentially with the axes so a regression hides in the
/// exponent. The compliant shape is the table of cases plus one loop, whose
/// case count a reader counts by eye and grows linearly with the record.
///
/// Every frontend emits the fact only in test context, so the rule needs no
/// path or context filter of its own — it is the authority on the message,
/// not on the detection (the extractor, which owns the language syntax, is).
///
/// ```
/// use core_ai_native_conform::rules::DeclaredTestMatrices;
/// use core_ai_native_conform::{Fact, Rule, SourceFacts};
///
/// let rule = DeclaredTestMatrices;
/// let sf = SourceFacts {
///     file: "crates/x/src/lib.rs".into(),
///     crate_name: "x".into(),
///     facts: vec![
///         Fact::TestSweep { kind: "bitmask".into(), line: 12, detail: "1 << n".into() },
///         Fact::TestSweep { kind: "nested-loops".into(), line: 30, detail: "3".into() },
///     ],
/// };
/// let findings = rule.check(&[sf]);
/// assert_eq!(findings.len(), 2);
/// assert!(findings.iter().all(|f| f.rule == "declared-test-matrices"));
/// assert!(core_ai_native_conform::rules::matches_req_grammar(&findings[0].message));
/// // The fingerprint is file + kind + ordinal, never line (the stop.rs
/// // 33→35 lesson): a line-keyed baseline rots on any edit above the loop,
/// // and a baseline that rots on unrelated edits is a checker that lies.
/// assert_eq!(findings[0].fingerprint, "declared-test-matrices|crates/x/src/lib.rs|bitmask#0");
/// assert_eq!(findings[1].fingerprint, "declared-test-matrices|crates/x/src/lib.rs|nested-loops#0");
/// // A clean tree (no swept matrix) is silent.
/// let clean = SourceFacts {
///     file: "crates/x/src/lib.rs".into(),
///     crate_name: "x".into(),
///     facts: vec![],
/// };
/// assert!(rule.check(&[clean]).is_empty());
/// ```
pub struct DeclaredTestMatrices;

impl Rule for DeclaredTestMatrices {
    fn id(&self) -> &'static str {
        "declared-test-matrices"
    }
    fn why(&self) -> &'static str {
        "test matrices are declared as data, never swept — a 2^n bit-mask \
         or a 3+-deep Cartesian loop generates cases the reader cannot count \
         by eye, so a regression hides in the exponent; declare the table and \
         iterate it once (R-060)"
    }
    fn check(&self, facts: &[SourceFacts]) -> Vec<Finding> {
        let mut out = Vec::new();
        for sf in facts {
            // Per-file per-kind ordinal fingerprints, never line numbers
            // (the stop.rs lesson): the ordinal advances over EVERY
            // TestSweep fact of this kind before any filter, so a neighbour
            // gaining or losing a swept matrix never re-keys a frozen entry.
            let mut seen: std::collections::BTreeMap<&str, u32> = std::collections::BTreeMap::new();
            for f in &sf.facts {
                let Fact::TestSweep { kind, line, detail } = f else {
                    continue;
                };
                let counter = seen.entry(kind.as_str()).or_insert(0);
                let ordinal = *counter;
                *counter += 1;
                let (why, fix) = match kind.as_str() {
                    "bitmask" => (
                        format!(
                            "a loop bound sweeps `2^n` (`{detail}`) — the case \
                             count grows exponentially with the axes"
                        ),
                        "declare the cases as data (a table of cases iterated \
                         once), not a generated bit-mask",
                    ),
                    // nested-loops, and any future kind: the depth is the
                    // detail, the remedy the same declared-table shape.
                    _ => (
                        format!(
                            "a test nests loops {detail}-deep — a Cartesian \
                             product of axes whose case count grows exponentially"
                        ),
                        "declare the cases as data and iterate the table once, \
                         not as nested loops",
                    ),
                };
                out.push(Finding {
                    rule: self.id(),
                    file: sf.file.clone(),
                    line: *line,
                    message: req_message(MATRICES_CARD, &why, fix),
                    why: self.why(),
                    fingerprint: format!("declared-test-matrices|{}|{kind}#{ordinal}", sf.file),
                });
            }
        }
        out.sort();
        out
    }
}
